// Agoda — binary search on the answer: ship within D days (LeetCode 1011), eating speed (LeetCode 875).
public static class ShipCapacity {
    // Smallest belt capacity that ships every package, in order, within `days` days.
    public static int ShipWithinDays(int[] weights, int days) {
        if (weights == null || weights.Length == 0) return 0;
        if (days <= 0) throw new ArgumentOutOfRangeException(nameof(days));
        long lo = 0, hi = 0;
        foreach (var w in weights) { if (w <= 0) throw new ArgumentOutOfRangeException(nameof(weights)); lo = Math.Max(lo, w); hi += w; }
        while (lo < hi) {                                // invariant: the answer is in [lo, hi]
            long mid = lo + (hi - lo) / 2;
            if (DaysNeeded(weights, mid) <= days) hi = mid; else lo = mid + 1;
        }
        return (int)lo;
    }

    static int DaysNeeded(int[] w, long cap) {
        int d = 1; long load = 0;
        foreach (var x in w) { if (load + x > cap) { d++; load = 0; } load += x; }
        return d;
    }

    // Smallest integer speed k (bananas per hour) that finishes every pile within h hours.
    public static int MinEatingSpeed(int[] piles, int h) {
        if (piles == null || piles.Length == 0) return 0;
        if (h < piles.Length) throw new ArgumentException("h must be at least the number of piles");
        long lo = 1, hi = 0;
        foreach (var p in piles) hi = Math.Max(hi, p);
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long hours = 0;
            foreach (var p in piles) { hours += (p + mid - 1) / mid; if (hours > h) break; }
            if (hours <= h) hi = mid; else lo = mid + 1;
        }
        return (int)lo;
    }
}
